package dev.jobflow.service;
import com.fasterxml.jackson.databind.JsonNode; import dev.jobflow.api.JobDtos.*; import dev.jobflow.domain.*; import dev.jobflow.repo.*; import java.time.*; import java.util.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*;
@Service public class JobService {private final JobRepository jobs;private final RateLimitService limits;private final JobCreationPersistence creations;private final int maxPayload; public JobService(JobRepository j,RateLimitService l,JobCreationPersistence c,@org.springframework.beans.factory.annotation.Value("${jobflow.worker.max-payload-bytes}")int m){jobs=j;limits=l;creations=c;maxPayload=m;}
 public Job create(UUID ownerId,CreateJobRequest r,String key){if(key==null||key.isBlank()||key.length()>128)throw new IllegalArgumentException("Idempotency-Key header (1-128 characters) is required");if(r.payload().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>maxPayload)throw new IllegalArgumentException("Payload exceeds configured size limit");var existing=jobs.findByOwnerIdAndIdempotencyKey(ownerId,key);if(existing.isPresent())return existing.get();limits.check("submit:"+ownerId);try{return creations.insert(ownerId,r,key);}catch(DataIntegrityViolationException e){return jobs.findByOwnerIdAndIdempotencyKey(ownerId,key).orElseThrow(()->e);}}
 @Transactional(readOnly=true) public Job getForOwner(UUID id,UUID owner){return jobs.findByIdAndOwnerId(id,owner).orElseThrow(()->new NoSuchElementException("Job not found"));} @Transactional(readOnly=true) public Page<Job> listForOwner(UUID owner,Pageable p){return jobs.findByOwnerId(owner,p);} @Transactional public Job cancel(UUID id,UUID owner){Job j=getForOwner(id,owner);j.cancel();return j;} @Transactional(readOnly=true) public Page<Job> listAdmin(JobStatus status,Pageable p){return status==null?jobs.findAll(p):jobs.findByStatus(status,p);} @Transactional public Job replay(UUID id){Job j=jobs.findById(id).orElseThrow(()->new NoSuchElementException("Job not found"));j.replay();return j;}
 @Transactional public Optional<Job> claimNext(Duration lease){return jobs.lockNextEligibleId().flatMap(id->jobs.findById(id).map(j->{j.claim(Instant.now().plus(lease));return j;}));} @Transactional(readOnly=true) public Job processing(UUID id){Job j=jobs.findById(id).orElseThrow();if(j.getStatus()!=JobStatus.PROCESSING)throw new IllegalStateException("Job is no longer processing");return j;} @Transactional public void complete(UUID id,JsonNode result){processing(id).complete(result);} @Transactional public void fail(UUID id,String code,String message,boolean retryable,Instant next){Job j=processing(id);if(retryable&&j.getAttemptCount()<j.getMaxAttempts())j.retry(next,code,message);else j.deadLetter(code,message);} @Transactional public List<Job> recoverExpired(){List<Job> expired=jobs.findExpiredLeases(Instant.now());expired.forEach(Job::recoverExpired);return expired;}}
